function drawObject(o,w,editing=false){if(![o.x,o.y,o.w,o.h].every(Number.isFinite)||o.w<=0||o.h<=0||o.w>4000||o.h>2000||Math.abs(o.x)>10000||Math.abs(o.y)>10000){textCanvas('INVALID '+o.id,Number.isFinite(o.x)?o.x:0,Number.isFinite(o.y)?o.y:20,'#ff916f','10px ui-monospace');return}const active=o.active;const onColor=settings.contrast?'#d7ffd0':'#b9dfba';switch(o.type){case 'solid':rect(o.x,o.y,o.w,o.h,'#283629');rect(o.x,o.y,o.w,4,'#677857');rect(o.x,o.y+4,o.w,8,'#3e5037');for(let x=o.x+8;x<o.x+o.w;x+=32){line(x,o.y+22,x+14,o.y+36,'#3d4c33');line(x+14,o.y+22,x,o.y+36,'#3d4c33')}line(o.x,o.y+o.h-1,o.x+o.w,o.y+o.h-1,'#15241c');break;case 'oneway':rect(o.x,o.y,o.w,o.h,'#5d7252',2);rect(o.x,o.y,o.w,3,'#b0c391');for(let x=o.x+9;x<o.x+o.w;x+=24)line(x,o.y+4,x+5,o.y+9,'#283c29');textCanvas('↑',o.x+o.w/2,o.y-8,'#819a70','11px ui-monospace','center');break;case 'plate':rect(o.x-4,o.y+o.h-4,o.w+8,6,'#202b22',2);rect(o.x,o.y+(active?4:0),o.w,o.h-(active?4:0),active?onColor:'#847a58',2);for(let x=o.x+8;x<o.x+o.w-4;x+=14)rect(x,o.y+o.h-3,6,2,active?'#668857':'#d2b988');line(o.x+o.w/2,o.y+15,o.x+o.w/2,o.y+26,active?'#b9dfba80':'#766e5250');textCanvas(o.channel,o.x+o.w/2,o.y+39,active?onColor:'#b8b19a','11px ui-monospace','center');break;case 'door':{const target=o.open?1:0,prev=doorVisual.get(o)||0,v=editing?0:settings.motion?target:prev+(target-prev)*.18;doorVisual.set(o,v);rect(o.x-6,o.y-6,o.w+12,o.h+6,'#18241e',3);rect(o.x-4,o.y-5,3,o.h+5,'#6c7857');rect(o.x+o.w+1,o.y-5,3,o.h+5,'#6c7857');if(v<.98){const dh=o.h*(1-v);rect(o.x,o.y,o.w,dh,'#4b5040');for(let y=o.y+9;y<o.y+dh-5;y+=22){rect(o.x+2,y,o.w-4,5,'#747354');line(o.x+4,y+7,o.x+o.w-4,y+17,'#303c2b')}rect(o.x+o.w/2-3,o.y+Math.max(12,dh/2)-11,6,Math.min(22,dh),'#ffa47a',2)}else{rect(o.x,o.y,o.w,12,'#8a9e70');ctx.globalAlpha=.16;rect(o.x,o.y+12,o.w,o.h-12,onColor);ctx.globalAlpha=1}rect(o.x-5,o.y-11,o.w+10,7,o.open?onColor:'#d99c72',2);textCanvas(o.channel,o.x+o.w/2,o.y-23,o.open?onColor:'#d9bfa0','12px ui-monospace','center');if(o.open)textCanvas('OPEN',o.x+o.w/2,o.y+o.h+20,onColor,'8px ui-monospace','center');break}case 'crate':rect(o.x-2,o.y-2,o.w+4,o.h+4,'#2b281e',4);rect(o.x,o.y,o.w,o.h,'#c6b27b',3);rect(o.x+4,o.y+4,o.w-8,o.h-8,'#6c714c',2);line(o.x+5,o.y+5,o.x+o.w-5,o.y+o.h-5,'#d9c98e',2);line(o.x+o.w-5,o.y+5,o.x+5,o.y+o.h-5,'#d9c98e',2);rect(o.x+o.w/2-3,o.y+o.h/2-3,6,6,'#f1dfa5',1);break;case 'goal':ctx.strokeStyle='#a9c48c';ctx.lineWidth=2;rr(ctx,o.x,o.y,o.w,o.h,Math.min(24,o.w/2));ctx.stroke();ctx.globalAlpha=.15;rect(o.x-6,o.y-5,o.w+12,o.h+10,'#b9dfba',24);ctx.globalAlpha=1;rect(o.x+6,o.y+7,o.w-12,o.h-8,'#8fae7514',16);line(o.x+o.w/2-8,o.y+o.h/2,o.x+o.w/2+8,o.y+o.h/2,onColor,2);line(o.x+o.w/2+2,o.y+o.h/2-6,o.x+o.w/2+8,o.y+o.h/2,onColor,2);line(o.x+o.w/2+2,o.y+o.h/2+6,o.x+o.w/2+8,o.y+o.h/2,onColor,2);textCanvas('EXIT',o.x+o.w/2,o.y-17,onColor,'9px ui-monospace','center');break;case 'toggle':case 'timed':rect(o.x,o.y,o.w,o.h,'#596249',4);rect(o.x+3,o.y+3,o.w-6,o.h-6,'#273d2c',3);rect(o.x+6,o.y+7,o.w-12,8,active?onColor:'#e9b491',2);if(o.type==='timed'){textCanvas('◷',o.x+o.w/2,o.y+29,'#ddcc9b','12px ui-monospace','center');if(o.timer)textCanvas(fmt(o.timer/60),o.x+o.w/2,o.y-22,onColor,'10px ui-monospace','center')}else line(o.x+o.w/2,o.y+19,o.x+o.w/2+(active?4:-4),o.y+29,'#e4dda7',2);textCanvas(o.channel,o.x+o.w/2,o.y-8,active?onColor:'#bdb7a0','10px ui-monospace','center');break;case 'lift':if(editing||$('diagToggle').checked){ctx.setLineDash([5,5]);line(o.bx??o.x,o.by??o.y,(o.bx??o.x)+(o.dx||0),(o.by??o.y)+(o.dy||0),'#d9cc9880');ctx.setLineDash([])}rect(o.x,o.y,o.w,o.h,'#8da081',3);rect(o.x,o.y,o.w,4,'#d5dcb3');for(let x=o.x+8;x<o.x+o.w;x+=17)rect(x,o.y+6,8,4,'#3c5541');textCanvas('TRANSIT',o.x+o.w/2,o.y-10,'#c6d4a9','8px ui-monospace','center');break;case 'laser':{const ison=editing||o.active;rect(o.x-5,o.y-10,o.w+10,10,'#8b614c',3);rect(o.x-3,o.y-4,o.w+6,4,ison?'#ffb18a':'#b9dfba',1);ctx.globalAlpha=ison?.15:.1;rect(o.x-5,o.y,o.w+10,o.h,ison?'#ff775f':'#b9dfba');ctx.globalAlpha=1;if(ison){rect(o.x,o.y,o.w,o.h,settings.flash?'#e5a088':'#fa9576');rect(o.x+o.w/2-1,o.y,2,o.h,'#ffd2a9')}else{ctx.setLineDash([3,9]);line(o.x+o.w/2,o.y,o.x+o.w/2,o.y+o.h,'#91ac81');ctx.setLineDash([])}textCanvas(o.channel+' / BEAM',o.x+o.w/2,o.y-22,ison?'#e9a183':onColor,'8px ui-monospace','center');break}case 'hazard':rect(o.x,o.y,o.w,o.h,'#ac6245');for(let x=o.x+4;x<o.x+o.w;x+=16){ctx.beginPath();ctx.moveTo(x,o.y+o.h);ctx.lineTo(x+6,o.y+2);ctx.lineTo(x+12,o.y+o.h);ctx.fillStyle='#e39b67';ctx.fill()}break;case 'checkpoint':line(o.x+4,o.y,o.x+4,o.y+o.h,'#cbd6a5',2);ctx.beginPath();ctx.moveTo(o.x+5,o.y);ctx.lineTo(o.x+25,o.y+7);ctx.lineTo(o.x+5,o.y+14);ctx.fillStyle=o.active?'#b9dfba':'#9cb4b8';ctx.fill();break;case 'spawn':if(editing){ctx.setLineDash([3,3]);ctx.strokeStyle='#ff916f';ctx.strokeRect(o.x,o.y,o.w,o.h);ctx.setLineDash([]);textCanvas('SPAWN',o.x+o.w/2,o.y-10,'#ff916f','9px ui-monospace','center')}break;}if($('diagToggle').checked||editing){ctx.strokeStyle=editing?'#97b38640':'#9de8d870';ctx.lineWidth=1;ctx.strokeRect(o.x,o.y,o.w,o.h);if($('diagToggle').checked){textCanvas(o.id,o.x,o.y-6,'#8dd9d2','8px ui-monospace');if(o.type==='crate'&&!o.heldBy)drawContacts(o)}}}
function drawContacts(b){for(const n of b.contacts||[]){const x=n.nx<0?b.x+b.w:n.nx>0?b.x:b.x+b.w/2,y=n.ny<0?b.y+b.h:n.ny>0?b.y:b.y+b.h/2;line(x,y,x+n.nx*16,y+n.ny*16,'#e9efa5',2);const ex=x+n.nx*16,ey=y+n.ny*16;line(ex,ey,ex-n.nx*4+n.ny*3,ey-n.ny*4-n.nx*3,'#e9efa5',1);line(ex,ey,ex-n.nx*4-n.ny*3,ey-n.ny*4+n.nx*3,'#e9efa5',1)}}
function drawActor(a){if(a.dead)return;const color=a.rec?COLORS[a.index]:'#ff916f';if(a.rec&&!settings.motion){for(let i=0;i<a.trail.length;i+=2){const p=a.trail[i];ctx.globalAlpha=i/a.trail.length*.2;rect(p.x-10,p.y-15,20,31,color,5)}ctx.globalAlpha=1}ctx.save();if(a.rec)ctx.globalAlpha=.84;rect(a.x-2,a.y-2,28,32,'#12251e',8);rect(a.x,a.y,24,29,color,7);rect(a.x+4,a.y+7,16,10,'#283b32',3);rect(a.x+(a.face>0?13:5),a.y+10,6,3,'#ecedc3',1);rect(a.x+3,a.y+28,7,8,color,2);rect(a.x+14,a.y+28,7,8,color,2);rect(a.x-4,a.y+16,5,11,color,2);rect(a.x+23,a.y+16,5,11,color,2);ctx.restore();textCanvas(a.rec?'E'+(a.index+1):'YOU',a.x+12,a.y-11,color,'8px ui-monospace','center');if(a.warning)textCanvas('⚠ DRIFT',a.x+12,a.y-22,'#ffb090','8px ui-monospace','center');if($('diagToggle').checked){ctx.strokeStyle='#f0efb6';ctx.strokeRect(a.x,a.y,a.w,a.h);drawContacts(a)}}
function drawWorld(){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,cw,ch);ctx.fillStyle='#18261d';ctx.fillRect(0,0,cw,ch);const editing=mode==='editor',w=editing?{level:editor.level,objects:editor.level.objects,actors:[]}:inspection||world;ctx.save();if(editing){scale=editor.zoom;camX=editor.panX;camY=editor.panY;ctx.translate(camX,camY);ctx.scale(scale,scale)}else{scale=Math.max(cw/w.level.width,ch/w.level.height);const visibleWidth=cw/scale;const target=Math.max(0,Math.min(w.level.width-visibleWidth,w.player.x+12-visibleWidth*.34));camX=settings.motion?target:camX+(target-camX)*.075;if(visibleWidth>=w.level.width)camX=-(visibleWidth-w.level.width)/2;const targetY=Math.max(0,Math.min(w.level.height-ch/scale,w.player.y+w.player.h-(ch/scale)*.76));camY=settings.motion?targetY:camY+(targetY-camY)*.09;ctx.scale(scale,scale);ctx.translate(-camX,-camY)}background(w.level);if(editing){ctx.strokeStyle='#cbdeac30';ctx.lineWidth=.5/editor.zoom;for(let x=0;x<=w.level.width;x+=editor.grid){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,w.level.height);ctx.stroke()}for(let y=0;y<=w.level.height;y+=editor.grid){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w.level.width,y);ctx.stroke()}ctx.strokeStyle='#adc39b';ctx.lineWidth=2/editor.zoom;ctx.strokeRect(0,0,w.level.width,w.level.height)}
if(!editing){for(const plate of w.objects.filter(o=>['plate','toggle','timed'].includes(o.type))){for(const door of w.objects.filter(o=>['door','laser'].includes(o.type)&&o.channel===plate.channel)){ctx.setLineDash([2,6]);const yy=455+(plate.channel.charCodeAt(0)%3)*13;line(plate.x+plate.w/2,plate.y+plate.h,plate.x+plate.w/2,yy,plate.active?'#93b98277':'#7d805033');line(plate.x+plate.w/2,yy,door.x+door.w/2,yy,plate.active?'#93b98277':'#7d805033');line(door.x+door.w/2,yy,door.x+door.w/2,door.y+door.h,plate.active?'#93b98277':'#7d805033');ctx.setLineDash([])}}}
for(const o of w.objects.filter(o=>o.type!=='crate'))drawObject(o,w,editing);for(const a of w.actors)drawActor(a);for(const o of w.objects.filter(o=>o.type==='crate'))drawObject(o,w,editing);if(!editing){const a=w.player;const nearby=w.objects.find(o=>['crate','timed','toggle'].includes(o.type)&&Math.hypot(o.x-a.x,o.y-a.y)<68);if(nearby||a.carry){const msg=a.carry?'E DROP · Q THROW':nearby.type==='crate'?'E CARRY':'E ACTIVATE';rect(a.x-40,a.y-46,105,19,'#14251ee8',4);textCanvas(msg,a.x+12,a.y-33,'#d8dec0','8px ui-monospace','center')}for(const p of particles){ctx.globalAlpha=p.life;rect(p.x,p.y,3,3,p.color,1)}ctx.globalAlpha=1}
if(editing){for(const id of editor.selected){const o=editor.level.objects.find(o=>o.id===id);if(!o)continue;ctx.strokeStyle='#ffab82';ctx.lineWidth=2/editor.zoom;ctx.strokeRect(o.x,o.y,o.w,o.h);rect(o.x+o.w-4/editor.zoom,o.y+o.h-4/editor.zoom,8/editor.zoom,8/editor.zoom,'#ff916f',1);textCanvas(o.id,o.x,o.y-7,'#ffad86',(9/editor.zoom)+'px ui-monospace')}if(editor.box){ctx.fillStyle='#b9dfba20';ctx.fillRect(editor.box.x,editor.box.y,editor.box.w,editor.box.h);ctx.strokeStyle='#b9dfba';ctx.lineWidth=1/editor.zoom;ctx.strokeRect(editor.box.x,editor.box.y,editor.box.w,editor.box.h)}const v=E.validate(editor.level);for(const err of v.errors){const o=editor.level.objects.find(o=>err.startsWith(o.id+':'));if(o){ctx.strokeStyle='#ff654f';ctx.lineWidth=3/editor.zoom;ctx.strokeRect(o.x,o.y,o.w,o.h)}}}
ctx.restore();}
function drawTimeline(){if(!tw||mode==='editor')return;tx.setTransform(dpr,0,0,dpr,0,0);tx.clearRect(0,0,tw,92);const left=58,right=10,width=tw-left-right,sec=level.duration;tx.font='8px ui-monospace';tx.textBaseline='middle';for(let s=0;s<=sec;s+=sec>20?5:2){const x=left+s/sec*width;tx.fillStyle='#8e9c8b';tx.fillText(s+'s',x-4,7);tx.strokeStyle='#3e4d3e';tx.beginPath();tx.moveTo(x,16);tx.lineTo(x,84);tx.stroke()}const lanes=[...recordings.map((r,i)=>({r,name:'ECHO '+(i+1),color:COLORS[i]})),{r:{inputs:world.inputs,events:world.events},name:'YOU',color:'#ff916f'}];const h=Math.min(20,65/lanes.length);lanes.forEach((lane,i)=>{const y=20+i*h;tx.fillStyle=lane.color;tx.fillText(lane.name,0,y+h/2);tx.fillStyle='#111b17';tx.fillRect(left,y,width,h-4);let start=0,last=lane.r.inputs[0]||0;for(let f=1;f<=lane.r.inputs.length;f++){const mask=lane.r.inputs[f]||0;if(mask!==last||f===lane.r.inputs.length){tx.globalAlpha=last?.65:.14;tx.fillStyle=lane.color;tx.fillRect(left+start/(sec*60)*width,y,Math.max(1,(f-start)/(sec*60)*width),h-4);if(last&4){tx.globalAlpha=1;tx.fillRect(left+start/(sec*60)*width,y,2,h-4)}start=f;last=mask}}tx.globalAlpha=1;for(const ev of lane.r.events){tx.fillStyle='#ede8b7';const x=left+ev.frame/(sec*60)*width;tx.beginPath();tx.moveTo(x,y+2);tx.lineTo(x+3,y+5);tx.lineTo(x,y+8);tx.lineTo(x-3,y+5);tx.closePath();tx.fill()}});const frame=inspection?inspectFrame:world.frame,x=left+frame/(sec*60)*width;tx.strokeStyle='#ede9ca';tx.lineWidth=1;tx.beginPath();tx.moveTo(x,15);tx.lineTo(x,88);tx.stroke();tx.fillStyle='#ecf0dc';tx.beginPath();tx.moveTo(x-3,13);tx.lineTo(x+3,13);tx.lineTo(x,18);tx.fill();}
let modalWasPaused=false,modalFocus=null;
function showModal(title,content){modalWasPaused=paused;paused=true;clearInput();modalFocus=document.activeElement;$('modal').innerHTML='<div class="modal-top"><h2 id="modalTitle"></h2><button class="ghost iconbtn" id="closeModalBtn" aria-label="Close dialog">✕</button></div>';$('modalTitle').textContent=title;if(typeof content==='string')$('modal').insertAdjacentHTML('beforeend',content);else $('modal').append(content);$('modalBackdrop').classList.add('open');$('closeModalBtn').onclick=()=>closeModal();$('closeModalBtn').focus();updatePauseUI()}
function closeModal(resume=true){remapping=null;$('modalBackdrop').classList.remove('open');if(resume)paused=modalWasPaused;acc=0;clearInput();updatePauseUI();if(modalFocus?.isConnected)modalFocus.focus()}
function showLevels(){const frag=document.createDocumentFragment(),p=document.createElement('p');p.textContent='Six experiments. One extraordinary teammate. Replay any chamber to improve your rank.';frag.append(p);const grid=document.createElement('div');grid.className='levelgrid';levels.forEach((lev,i)=>{const b=document.createElement('button');b.className='levelcard';b.ariaLabel='Play chamber '+(i+1)+': '+lev.name;const num=document.createElement('span');num.className='num';num.textContent='CHAMBER '+pad(i+1);const h=document.createElement('h3');h.textContent=lev.name;const p=document.createElement('p');p.textContent=lev.difficulty;const rank=document.createElement('span');rank.className='rank';const saved=progress[i];rank.textContent=saved?`${saved.rank} · ${saved.loops} LOOP${saved.loops===1?'':'S'} · ${saved.time.toFixed(1)}s`:'○ AWAITING DISCOVERY';b.append(num,h,p,rank);b.onclick=()=>loadLevel(i);grid.append(b)});frag.append(grid);showModal('Choose your chamber.',frag)}
function showGuide(){showModal('Meet your best teammate.',`<p>It’s you, a few seconds ago. Move, interact, and record a loop. Your echo repeats those inputs on the same physical timeline while you do something new.</p><div class="guide-steps"><div class="guide-step"><strong>01</strong><h3>Do something useful.</h3><p>Stand on a pressure plate, carry a core, or activate a switch. Use arrows / A D to move, Space to jump, E to interact, Q to throw.</p></div><div class="guide-step"><strong>02</strong><h3>Leave an echo.</h3><p>Press R or Record & rewind. The world resets; your echo repeats your loop, then holds its final position. Up to five echoes can work together.</p></div><div class="guide-step"><strong>03</strong><h3>Change the outcome.</h3><p>Let your echo hold a plate while you reach the exit. Matching letters connect switches, doors and beams. Shared objects can change an echo’s path.</p></div></div><p><b>Time controls:</b> P or Escape pauses. Click the paused timeline to inspect its past without changing it. Step advances one frame; 1× speed switches to quarter speed. Shift+R restarts, U removes the last echo.</p><p><b>Gamepad:</b> stick / D-pad moves, A jumps, X interacts, B throws, Y records, Start pauses. Touch controls support movement and jumping together.</p><p><b>Workshop:</b> choose an object and click the room to place it. Select and drag to move, drag the corner to resize, Shift-click or box-select for groups. Use Pan and the zoom buttons on touch. Channels connect objects; JSON contains data only.</p><div class="modal-actions"><button class="primary" id="guideReady">I’m ready</button></div>`);$('guideReady').onclick=()=>closeModal()}
function showSettings(){showModal('Tune your experience.',`<p>All preferences stay on this device. Controls always support arrow keys and W / ↑ for jumping.</p><div class="settings-grid"><label>Master volume<input id="volumeInput" type="range" min="0" max="1" step=".01" value="${settings.volume}"></label><label class="check"><input id="musicInput" type="checkbox" ${settings.music?'checked':''}> Ambient music</label><label class="check"><input id="motionInput" type="checkbox" ${settings.motion?'checked':''}> Reduced motion</label><label class="check"><input id="flashInput" type="checkbox" ${settings.flash?'checked':''}> Reduced flash</label><label class="check"><input id="contrastInput" type="checkbox" ${settings.contrast?'checked':''}> High contrast</label><label class="check"><input id="diagInput" type="checkbox" ${$('diagToggle').checked?'checked':''}> Physics diagnostics</label></div><div class="panel-heading">REMAP CONTROLS · CLICK A KEY, THEN PRESS ITS REPLACEMENT</div><div class="settings-grid" id="remapGrid"></div><div class="modal-actions"><button id="defaultsBtn">Restore defaults</button><button class="primary" id="settingsDone">Done</button></div>`);for(const [key,label] of [['left','Move left'],['right','Move right'],['jump','Jump'],['interact','Interact / carry'],['throw','Throw']]){const wrap=document.createElement('label');wrap.textContent=label;const b=document.createElement('button');b.className='small';b.id='remap-'+key;b.ariaLabel='Remap '+label.toLowerCase();b.textContent=settings[key].replace('Key','');b.onclick=()=>{b.textContent='Press a key…';remapping={key,button:b}};wrap.append(b);$('remapGrid').append(wrap)}for(const [id,key] of [['musicInput','music'],['motionInput','motion'],['flashInput','flash'],['contrastInput','contrast']])$(id).onchange=()=>{settings[key]=$(id).checked;applySettings();writeStore('echo.settings',settings)};$('volumeInput').oninput=()=>{settings.volume=+$('volumeInput').value;applySettings();writeStore('echo.settings',settings)};$('diagInput').onchange=()=>{$('diagToggle').checked=$('diagInput').checked;toggleDiagnostics()};$('defaultsBtn').onclick=()=>{settings={...defaults};applySettings();writeStore('echo.settings',settings);closeModal();showSettings()};$('settingsDone').onclick=()=>closeModal()}
function showVictory(){const time=elapsedTotal+world.frame/60,rank=recordings.length<=(levelIndex===5?3:levelIndex===1?2:1)&&world.deaths===0?'GOLD':world.deaths<3?'SILVER':'BRONZE';if(levelIndex>=0&&!playTesting){const old=progress[levelIndex];if(!old||time<old.time)progress[levelIndex]={rank,time,loops:loopAttempts};writeStore('echo.progress',progress)}showModal('Experiment complete.',`<div class="victory"><div class="victory-orbit">✧</div><div class="eyebrow">${rank} · TIMELINE RESOLVED</div><h2 style="margin-top:12px">${levelIndex===5&&!playTesting?'Every you made it.':'A little help from yourself.'}</h2><p>${levelIndex===5&&!playTesting?'You’ve completed all six experiments. Time well spent.':'The door was only the beginning. Your past and present make a good team.'}</p><div class="victory-stats"><div><strong>${loopAttempts}</strong><span>LOOPS</span></div><div><strong>${time.toFixed(1)}s</strong><span>TOTAL TIME</span></div><div><strong>${recordings.length}</strong><span>ECHOES</span></div></div></div><div class="modal-actions"><button id="victoryTrace">Export solution</button><button id="victoryReplay">Replay room</button><button class="primary" id="victoryNext">${playTesting?'Return to workshop':levelIndex<5&&levelIndex>=0?'Next chamber →':'Choose a chamber'}</button></div>`);$('victoryTrace').onclick=exportTrace;$('victoryReplay').onclick=()=>{closeModal(false);restart()};$('victoryNext').onclick=()=>{if(playTesting)returnToEditor();else if(levelIndex>=0&&levelIndex<5)loadLevel(levelIndex+1);else{closeModal();showLevels()}}}
function downloadJSON(value,name){const blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),2000);toast('Exported '+name)}
function exportTrace(){downloadJSON({format:'echo-chamber-trace',version:1,timestep:60,level:E.validate(level).level,echoes:recordings,attempt:E.record(world),result:{won:world.won,frames:world.frame,loops:loopAttempts,divergence:world.divergence}},'echo-solution.json')}
const editor={level:E.clone(level),tool:'select',selected:new Set(),grid:16,zoom:.8,panX:0,panY:0,fitted:false,undo:[],redo:[],drag:null,box:null,multi:false};
const paletteNames={solid:'Wall',oneway:'One-way',spawn:'Spawn',goal:'Goal',plate:'Plate',toggle:'Toggle',timed:'Timed',door:'Door',lift:'Lift',laser:'Laser',hazard:'Hazard',crate:'Core',checkpoint:'Checkpoint'};
const paletteIcons={solid:'▰',oneway:'↥',spawn:'◉',goal:'⇥',plate:'▱',toggle:'⏻',timed:'◷',door:'▥',lift:'↔',laser:'┊',hazard:'△',crate:'◇',checkpoint:'⚑'};
for(const type of E.TYPES){const b=document.createElement('button');b.dataset.tool=type;b.ariaLabel='Place '+paletteNames[type];const icon=document.createElement('span');icon.textContent=paletteIcons[type];icon.style.fontSize='17px';const label=document.createElement('span');label.textContent=paletteNames[type];b.append(icon,label);b.onclick=()=>setTool(type);$('palette').append(b)}
function setTool(tool){editor.tool=tool;$('toolLabel').textContent=tool.toUpperCase();document.querySelectorAll('[data-tool]').forEach(b=>b.classList.toggle('selected',b.dataset.tool===tool));$('selectTool').classList.toggle('primary',tool==='select');$('panTool').classList.toggle('primary',tool==='pan');C.style.cursor=tool==='pan'?'grab':tool==='select'?'default':'crosshair';editor.drag=null;editor.box=null;updateUI()}
function snapshotEdit(){return E.clone(editor.level)}function pushEdit(previous){editor.undo.push(previous);if(editor.undo.length>80)editor.undo.shift();editor.redo=[];writeStore('echo.draft',editor.level);updateEditor()}
function edit(fn){const old=snapshotEdit();fn();pushEdit(old)}
function updateEditor(){const v=E.validate(editor.level);$('editorLevelName').value=editor.level.name;$('editorDuration').value=editor.level.duration;$('validationMsg').textContent=v.errors.length?v.errors.slice(0,5).join('\n'):`✓ ${editor.level.objects.length} objects · spawn & goal valid · channels linked`;$('validationMsg').style.whiteSpace='pre-line';$('validationMsg').classList.toggle('invalid',!!v.errors.length);$('undoEditBtn').disabled=!editor.undo.length;$('redoEditBtn').disabled=!editor.redo.length;updateProperties();updateLevelUI()}
function fitEditor(){if(!cw||!ch)return;editor.zoom=Math.min(cw/editor.level.width,ch/editor.level.height)*.92;editor.panX=(cw-editor.level.width*editor.zoom)/2;editor.panY=(ch-editor.level.height*editor.zoom)/2;editor.fitted=true}
function enterEditor(){if(playTesting){returnToEditor();return}closeModal(false);clearInput();if(mode!=='editor'){const draft=readStore('echo.draft',null);editor.level=E.restoreDraft(draft)||E.validate(level).level;editor.undo=[];editor.redo=[];editor.selected.clear()}mode='editor';paused=true;inspection=null;document.body.classList.add('editor-mode');setTool('select');editor.fitted=false;resize();fitEditor();updateEditor();toast('Workshop ready. Pick a tool and build an experiment.')}
function startPlaytest(){const v=E.validate(editor.level);if(v.errors.length){toast('Fix the room before play-testing: '+v.errors[0],true);$('validationMsg').textContent=v.errors.join('\n');return}clearInput();level=v.level;levelIndex=-1;recordings=[];world=E.create(level);mode='play';playTesting=true;paused=false;started=false;inspection=null;acc=0;elapsedTotal=0;loopAttempts=1;winShown=false;camX=0;document.body.classList.remove('editor-mode');updateLevelUI();toast('Play-test started. Your room stays saved in the workshop.')}
function returnToEditor(){closeModal(false);clearInput();mode='editor';playTesting=false;paused=true;inspection=null;document.body.classList.add('editor-mode');resize();fitEditor();updateEditor();toast('Back in the workshop. Edits and history preserved.')}
function historyEdit(redo=false){const from=redo?editor.redo:editor.undo,to=redo?editor.undo:editor.redo;if(!from.length)return;to.push(snapshotEdit());editor.level=from.pop();editor.selected.clear();writeStore('echo.draft',editor.level);updateEditor();toast(redo?'Edit restored.':'Edit undone.')}
function updateProperties(){const panel=$('properties');panel.replaceChildren();const pickLabel=document.createElement('label');pickLabel.className='field';pickLabel.style.cssText='font-size:10px;margin-top:12px';pickLabel.textContent='Select object by ID';const pick=document.createElement('select');pick.id='objectSelect';pick.ariaLabel='Select object by ID';const empty=document.createElement('option');empty.value='';empty.textContent='Pick an object…';pick.append(empty);editor.level.objects.forEach((o,i)=>{const option=document.createElement('option');option.value=String(i);option.textContent=o.id+' · '+paletteNames[o.type];if(editor.selected.size===1&&editor.selected.has(o.id))option.selected=true;pick.append(option)});pick.onchange=()=>{if(pick.value!==''){editor.selected=new Set([editor.level.objects[Number(pick.value)].id]);setTool('select');updateProperties()}};pickLabel.append(pick);panel.append(pickLabel);$('selectedCount').textContent=editor.selected.size+' OBJECT'+(editor.selected.size===1?'':'S');const selected=editor.level.objects.filter(o=>editor.selected.has(o.id));if(!selected.length){const p=document.createElement('p');p.textContent='Pick an object to inspect it. Drag to move; Shift-click or drag empty space to select several.';p.style.cssText='font-size:11px;color:var(--muted);line-height:1.6';panel.append(p);return}if(selected.length>1){const p=document.createElement('p');p.textContent=selected.length+' objects selected. Drag to move together; duplicate or delete the group.';p.style.cssText='font-size:11px;line-height:1.6;color:var(--muted)';panel.append(p);return}const o=selected[0],grid=document.createElement('div');grid.className='property-grid';const field=(key,label,type='number',options=null)=>{const wrap=document.createElement('label');wrap.textContent=label;if(['id','channel','auto','axis'].includes(key))wrap.className='wide';let input;if(options){input=document.createElement('select');for(const [val,text] of options){const option=document.createElement('option');option.value=val;option.textContent=text;input.append(option)}}else{input=document.createElement('input');input.type=type;if(type==='number')input.step=key==='period'||key==='seconds'||key==='duty'?'.1':'1';if(type==='text')input.maxLength=key==='id'?40:16}input.value=o[key]??(key==='channel'?'A':key==='seconds'?4:key==='period'?4:key==='duty'?.5:key==='auto'?'true':0);input.id='prop-'+key;input.ariaLabel=label;input.onchange=()=>{if(key==='id'&&(!/^[a-zA-Z0-9_-]+$/.test(input.value)||editor.level.objects.some(v=>v!==o&&v.id===input.value))){toast('Use a unique ID with letters, numbers, dashes or underscores.',true);input.value=o.id;return}const old=snapshotEdit(),oldId=o.id;if(key==='auto')o[key]=input.value==='true';else if(type==='number')o[key]=Number(input.value);else o[key]=input.value;if(key==='id'){editor.selected.delete(oldId);editor.selected.add(o.id)}pushEdit(old)};wrap.append(input);grid.append(wrap)};
field('id','Object ID','text');field('x','X');field('y','Y');field('w','Width');field('h','Height');if(['plate','toggle','timed','door','lift','laser'].includes(o.type))field('channel','Channel (matching letters link objects)','text');if(o.type==='timed')field('seconds','Active seconds');if(o.type==='lift'){field('dx','Travel X');field('dy','Travel Y');field('period','Cycle seconds');field('auto','Motion control','text',[['true','Always moving'],['false','Only when channel is active']])}if(o.type==='laser'){field('axis','Orientation','text',[['vertical','Vertical'],['horizontal','Horizontal']]);field('period','Pulse seconds (0 = steady)');field('duty','Active fraction (0.1–0.9)')}panel.append(grid)}
function duplicateSelection(){const selected=editor.level.objects.filter(o=>editor.selected.has(o.id)&&o.type!=='spawn');if(!selected.length)return;edit(()=>{editor.selected.clear();for(const original of selected){const o=E.clone(original);o.id=uniqueId(o.type);o.x=Math.min(editor.level.width-o.w,o.x+editor.grid);o.y=Math.min(editor.level.height-o.h,o.y+editor.grid);editor.level.objects.push(o);editor.selected.add(o.id)}});toast('Selection duplicated.')}
function deleteSelection(){if(!editor.selected.size)return;edit(()=>{editor.level.objects=editor.level.objects.filter(o=>!editor.selected.has(o.id));editor.selected.clear()})}
function rotateSelection(){if(!editor.selected.size)return;edit(()=>{for(const o of editor.level.objects.filter(o=>editor.selected.has(o.id))){if(o.type==='lift'){[o.dx,o.dy]=[-(o.dy||0),o.dx||0]}else{const cx=o.x+o.w/2,cy=o.y+o.h/2;[o.w,o.h]=[o.h,o.w];o.x=Math.max(0,Math.min(editor.level.width-o.w,Math.round((cx-o.w/2)/editor.grid)*editor.grid));o.y=Math.max(0,Math.min(editor.level.height-o.h,Math.round((cy-o.h/2)/editor.grid)*editor.grid));if(o.type==='laser')o.axis=o.axis==='horizontal'?'vertical':'horizontal'}}})}
function uniqueId(type){let n=1;while(editor.level.objects.some(o=>o.id===type+'-'+n))n++;return type+'-'+n}
function screenToWorld(clientX,clientY){const r=C.getBoundingClientRect();return{x:(clientX-r.left-editor.panX)/editor.zoom,y:(clientY-r.top-editor.panY)/editor.zoom}}
function snap(v){return Math.round(v/editor.grid)*editor.grid}
function place(type,p){const sizes={solid:[128,32],oneway:[96,12],spawn:[24,36],goal:[48,64],plate:[64,10],toggle:[24,36],timed:[24,36],door:[32,160],lift:[96,16],laser:[8,160],hazard:[64,16],crate:[32,32],checkpoint:[24,36]};const [w,h]=sizes[type],o=obj(uniqueId(type),type,Math.max(0,Math.min(editor.level.width-w,snap(p.x))),Math.max(0,Math.min(editor.level.height-h,snap(p.y))),w,h);if(['plate','toggle','timed','door','lift','laser'].includes(type))o.channel='A';if(type==='timed')o.seconds=4;if(type==='lift')Object.assign(o,{dx:0,dy:-96,period:4,auto:true});if(type==='laser')Object.assign(o,{axis:'vertical',period:0,duty:.5});edit(()=>{if(type==='spawn')editor.level.objects=editor.level.objects.filter(v=>v.type!=='spawn');editor.level.objects.push(o);editor.selected=new Set([o.id])});toast(paletteNames[type]+' placed · '+o.id)}
C.addEventListener('pointerdown',e=>{C.focus();if(mode!=='editor')return;e.preventDefault();C.setPointerCapture(e.pointerId);const p=screenToWorld(e.clientX,e.clientY);if(editor.tool==='pan'||e.button===1){editor.drag={kind:'pan',id:e.pointerId,sx:e.clientX,sy:e.clientY,px:editor.panX,py:editor.panY};return}if(editor.tool!=='select'){place(editor.tool,p);return}const objects=editor.level.objects;let hit=null;for(let i=objects.length-1;i>=0;i--){const o=objects[i];if(p.x>=o.x-4/editor.zoom&&p.x<=o.x+o.w+4/editor.zoom&&p.y>=o.y-4/editor.zoom&&p.y<=o.y+o.h+4/editor.zoom){hit=o;break}}if(hit){if(e.shiftKey||editor.multi){if(editor.selected.has(hit.id))editor.selected.delete(hit.id);else editor.selected.add(hit.id);updateProperties();return}const wasSelected=editor.selected.has(hit.id);if(!wasSelected)editor.selected=new Set([hit.id]);const radius=Math.min(8/editor.zoom,Math.min(hit.w,hit.h)*.3),resizing=wasSelected&&editor.selected.size===1&&Math.abs(p.x-hit.x-hit.w)<radius&&Math.abs(p.y-hit.y-hit.h)<radius;editor.drag={id:e.pointerId,kind:resizing?'resize':'move',p,old:snapshotEdit(),objects:objects.filter(o=>editor.selected.has(o.id)).map(o=>({...o})),changed:false};updateProperties()}else{if(!e.shiftKey&&!editor.multi)editor.selected.clear();editor.drag={kind:'box',id:e.pointerId,p};editor.box={x:p.x,y:p.y,w:0,h:0};updateProperties()}});
C.addEventListener('pointermove',e=>{if(mode!=='editor'||!editor.drag||editor.drag.id!==e.pointerId)return;const d=editor.drag,p=screenToWorld(e.clientX,e.clientY);if(d.kind==='pan'){editor.panX=d.px+e.clientX-d.sx;editor.panY=d.py+e.clientY-d.sy;return}if(d.kind==='box'){editor.box={x:Math.min(p.x,d.p.x),y:Math.min(p.y,d.p.y),w:Math.abs(p.x-d.p.x),h:Math.abs(p.y-d.p.y)};return}let dx=snap(p.x-d.p.x),dy=snap(p.y-d.p.y);if(d.kind==='move'){dx=Math.max(-Math.min(...d.objects.map(o=>o.x)),Math.min(editor.level.width-Math.max(...d.objects.map(o=>o.x+o.w)),dx));dy=Math.max(-Math.min(...d.objects.map(o=>o.y)),Math.min(editor.level.height-Math.max(...d.objects.map(o=>o.y+o.h)),dy))}for(const original of d.objects){const o=editor.level.objects.find(o=>o.id===original.id);if(d.kind==='move'){o.x=original.x+dx;o.y=original.y+dy}else{o.w=Math.max(4,Math.min(editor.level.width-o.x,snap(original.w+dx)));o.h=Math.max(4,Math.min(editor.level.height-o.y,snap(original.h+dy)))}d.changed=dx!==0||dy!==0}});
function endEditorPointer(e,cancel=false){if(!editor.drag||editor.drag.id!==e.pointerId)return;const d=editor.drag;if(d.kind==='box'&&editor.box&&!cancel){for(const o of editor.level.objects){if(E.overlap(o,editor.box))editor.selected.add(o.id)}updateProperties()}else if(['move','resize'].includes(d.kind)){if(cancel)editor.level=d.old;else if(d.changed)pushEdit(d.old)}editor.drag=null;editor.box=null;updateProperties()}
C.addEventListener('pointerup',e=>endEditorPointer(e));C.addEventListener('pointercancel',e=>endEditorPointer(e,true));C.addEventListener('lostpointercapture',e=>endEditorPointer(e,true));C.addEventListener('contextmenu',e=>e.preventDefault());
function zoomEditor(factor,x=cw/2,y=ch/2){const wx=(x-editor.panX)/editor.zoom,wy=(y-editor.panY)/editor.zoom;editor.zoom=Math.max(.15,Math.min(3,editor.zoom*factor));editor.panX=x-wx*editor.zoom;editor.panY=y-wy*editor.zoom}
C.addEventListener('wheel',e=>{if(mode!=='editor')return;e.preventDefault();const r=C.getBoundingClientRect();zoomEditor(e.deltaY>0?.9:1.1,e.clientX-r.left,e.clientY-r.top)},{passive:false});
for(const b of document.querySelectorAll('[data-input]')){b.addEventListener('pointerdown',e=>{e.preventDefault();if(mode!=='play'||paused)return;b.setPointerCapture(e.pointerId);pointerInputs.set(e.pointerId,Number(b.dataset.input));b.style.background='#4b5841';started=true;C.focus();if(!audio.enabled)enableAudio()});const end=e=>{pointerInputs.delete(e.pointerId);b.style.background=''};b.addEventListener('pointerup',end);b.addEventListener('pointercancel',end);b.addEventListener('lostpointercapture',end)}
let remapping=null;
window.addEventListener('keydown',e=>{if(remapping){e.preventDefault();if(['KeyR','KeyP','KeyU','Escape','Tab'].includes(e.code)){toast('R, P, U, Escape and Tab are reserved.',true);return}const fixed={ArrowLeft:'left',ArrowRight:'right',ArrowUp:'jump',KeyW:'jump',Space:'jump',Enter:'interact'};if(fixed[e.code]&&fixed[e.code]!==remapping.key){toast('That key is a fixed alternative for '+fixed[e.code]+'.',true);return}if(Object.entries(settings).some(([k,v])=>['left','right','jump','interact','throw'].includes(k)&&k!==remapping.key&&v===e.code)){toast('That key is already assigned.',true);return}settings[remapping.key]=e.code;remapping.button.textContent=e.code.replace('Key','');remapping=null;writeStore('echo.settings',settings);clearInput();return}const open=$('modalBackdrop').classList.contains('open');if(open){if(e.code==='Escape'){e.preventDefault();closeModal()}else if(e.code==='Tab'){const nodes=Array.from($('modal').querySelectorAll('button,input,select,textarea')).filter(n=>!n.disabled),first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}return}if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(e.target.tagName==='BUTTON'&&['Space','Enter'].includes(e.code))return;if(mode==='editor'){if((e.ctrlKey||e.metaKey)&&e.code==='KeyZ'){e.preventDefault();historyEdit(e.shiftKey);return}if((e.ctrlKey||e.metaKey)&&e.code==='KeyY'){e.preventDefault();historyEdit(true);return}if(e.code==='Delete'||e.code==='Backspace'){e.preventDefault();deleteSelection()}else if((e.ctrlKey||e.metaKey)&&e.code==='KeyD'){e.preventDefault();duplicateSelection()}else if(e.code==='Escape'){setTool('select');editor.selected.clear();updateProperties()}else if(e.code==='Enter'){e.preventDefault();startPlaytest()}return}if(['ArrowLeft','ArrowRight','ArrowUp','KeyW','Space','Enter',settings.left,settings.right,settings.jump,settings.interact,settings.throw].includes(e.code)){e.preventDefault();if(!paused){held.add(e.code);started=true;C.focus();if(!audio.enabled)enableAudio()}}if(e.repeat)return;if(e.code==='KeyR'){e.preventDefault();if(e.shiftKey)restart();else commitLoop()}if(e.code==='KeyU'){e.preventDefault();undoEcho()}if(e.code==='KeyP'||e.code==='Escape'){e.preventDefault();togglePause()}});
window.addEventListener('keyup',e=>held.delete(e.code));window.addEventListener('blur',()=>{clearInput();if(mode==='play'&&started&&!world.won){paused=true;inspection=null;updatePauseUI()}if(editor.drag){if(editor.drag.old)editor.level=editor.drag.old;editor.drag=null;editor.box=null}});document.addEventListener('visibilitychange',()=>{if(document.hidden){clearInput();if(mode==='play')paused=true;updatePauseUI()}});document.addEventListener('focusin',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))clearInput()});
function undoEcho(){if(!recordings.length)return;recordings.pop();loopAttempts=Math.max(1,loopAttempts-1);resetLoop();simulationStep.warned=false;toast('Last echo removed. Timeline reset.');updateUI()}
$('levelsBtn').onclick=showLevels;$('editorBtn').onclick=enterEditor;$('helpBtn').onclick=$('footerHelp').onclick=showGuide;$('settingsBtn').onclick=showSettings;$('recordBtn').onclick=commitLoop;$('restartBtn').onclick=restart;$('pauseBtn').onclick=togglePause;$('returnEditorBtn').onclick=returnToEditor;$('undoEchoBtn').onclick=undoEcho;$('clearEchoBtn').onclick=()=>{recordings=[];resetLoop(false);toast('All echoes cleared.');updateUI()};$('slowBtn').onclick=()=>{slow=!slow;$('slowBtn').textContent=slow?'¼× speed':'1× speed'};$('stepBtn').onclick=()=>{if(mode!=='play')return;paused=true;inspection=null;started=true;simulationStep(inputMask());acc=0;updatePauseUI();updateUI()};$('traceBtn').onclick=exportTrace;
function toggleDiagnostics(){$('diagnostics').classList.toggle('show',$('diagToggle').checked);updateUI();if(mode==='play'&&!$('modalBackdrop').classList.contains('open'))C.focus()}
$('diagToggle').onchange=toggleDiagnostics;
$('audioBtn').onclick=()=>{if(!audio.enabled){enableAudio();tone(392,.3,'sine',.1);toast('Procedural sound enabled.')}else{audio.enabled=false;audio.ac.suspend();$('audioBtn').ariaLabel='Enable sound';$('audioBtn').title='Enable procedural sound';$('audioBtn').innerHTML='<svg class="icon" viewBox="0 0 24 24"><path d="M11 4 5 9H2v6h3l6 5zM16 9l5 6m0-6-5 6"/></svg>'}};
TC.addEventListener('pointerdown',e=>{if(!paused){toast('Pause to inspect the timeline.');return}TC.setPointerCapture(e.pointerId);timelineScrub(e)});function timelineScrub(e){const r=TC.getBoundingClientRect();preview((e.clientX-r.left-58)/(r.width-68)*level.duration*60)}TC.addEventListener('pointermove',e=>{if(e.buttons&&paused)timelineScrub(e)});TC.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.code)){e.preventDefault();if(!paused)return;const cur=inspection?inspectFrame:world.frame;preview(e.code==='Home'?0:e.code==='End'?world.frame:cur+(e.code==='ArrowRight'?1:-1)*(e.shiftKey?60:6))}});
$('selectTool').onclick=()=>setTool('select');$('panTool').onclick=()=>setTool('pan');$('fitBtn').onclick=fitEditor;$('gridBtn').onclick=()=>{editor.grid=editor.grid===16?8:editor.grid===8?32:16;$('gridBtn').textContent='Grid: '+editor.grid;updateUI()};$('undoEditBtn').onclick=()=>historyEdit();$('redoEditBtn').onclick=()=>historyEdit(true);$('duplicateBtn').onclick=duplicateSelection;$('deleteBtn').onclick=deleteSelection;$('rotateBtn').onclick=rotateSelection;$('validateBtn').onclick=()=>{updateEditor();const v=E.validate(editor.level);toast(v.errors.length?v.errors[0]:'Room valid. All channels, bounds, spawn and goal checked.',!!v.errors.length)};
$('editorLevelName').onchange=()=>edit(()=>{editor.level.name=$('editorLevelName').value.trim()||'Untitled chamber'});$('editorDuration').onchange=()=>edit(()=>{editor.level.duration=+$('editorDuration').value});
$('newLevelBtn').onclick=()=>{edit(()=>{editor.level=base('My time experiment',12);editor.selected.clear()});fitEditor();setTool('select');toast('New room. Spawn, floor and goal are ready.')};
for(const [id,label,factor] of [['zoomOutBtn','− Zoom',.8],['zoomInBtn','+ Zoom',1.25]]){const b=document.createElement('button');b.id=id;b.className='small';b.textContent=label;b.ariaLabel=label;b.onclick=()=>zoomEditor(factor);$('fitBtn').before(b)}const multi=document.createElement('button');multi.className='small';multi.id='multiBtn';multi.textContent='Multi-select';multi.onclick=()=>{editor.multi=!editor.multi;multi.classList.toggle('primary',editor.multi)};$('fitBtn').before(multi);
$('exportLevelBtn').onclick=()=>{const v=E.validate(editor.level);if(v.errors.length){toast('Fix validation errors before exporting: '+v.errors[0],true);return}downloadJSON(v.level,'echo-level.json')};
$('importLevelBtn').onclick=()=>{showModal('Import a chamber.',`<p>Paste level JSON, or choose a local JSON file. Only known puzzle objects and bounded numeric properties are accepted. The imported room opens in the workshop.</p><label class="field">Level JSON<textarea id="importText" rows="11" spellcheck="false" placeholder="{ &quot;name&quot;: &quot;My chamber&quot;, ... }"></textarea></label><label class="field" style="margin-top:15px">Choose a JSON file<input type="file" id="importFile" accept=".json,application/json"></label><div class="import-error" id="importError" role="alert"></div><div class="modal-actions"><button class="primary" id="doImport">Validate & import</button></div>`);$('importFile').onchange=async()=>{const file=$('importFile').files[0];if(!file)return;if(file.size>256000){$('importError').textContent='File is too large. Maximum size is 256 KB.';return}$('importText').value=await file.text()};$('doImport').onclick=()=>{try{if($('importText').value.length>256000)throw new Error('Maximum size is 256 KB.');const raw=JSON.parse($('importText').value),v=E.validate(raw);if(v.errors.length)throw new Error(v.errors.slice(0,6).join('\n'));edit(()=>{editor.level=v.level;editor.selected.clear()});closeModal(false);mode='editor';paused=true;fitEditor();updateEditor();toast('JSON validated. Chamber imported.')}catch(e){$('importError').textContent=e.message}}};
$('saveSlotBtn').onclick=()=>{const v=E.validate(editor.level);if(v.errors.length){toast('Fix validation errors before saving: '+v.errors[0],true);return}showModal('Save a local chamber.',`<p>Named slots stay in this browser. Export JSON for a portable backup. Saving an existing name replaces that slot.</p><label class="field">Slot name<input id="slotName" type="text" maxlength="50"></label><div class="modal-actions"><button class="primary" id="doSaveSlot">Save chamber</button></div>`);$('slotName').value=editor.level.name;$('doSaveSlot').onclick=()=>{const name=$('slotName').value.trim();if(!name){toast('Enter a slot name.',true);return}slots={...slots,[name]:v.level};if(writeStore('echo.slots',slots)){closeModal();toast('Saved “'+name+'” locally.')}}};
$('loadSlotBtn').onclick=()=>{const frag=document.createDocumentFragment(),p=document.createElement('p');p.textContent='Load a saved room into the workshop. Your current edit can be recovered with Undo.';frag.append(p);const grid=document.createElement('div');grid.className='levelgrid';for(const name of Object.keys(slots)){const slot=slots[name],v=E.validate(slot);if(v.errors.length)continue;const b=document.createElement('button');b.className='levelcard';const h=document.createElement('h3');h.textContent=name;const p=document.createElement('p');p.textContent=v.level.objects.length+' objects · '+v.level.duration+' second loop';b.append(h,p);b.onclick=()=>{edit(()=>{editor.level=E.clone(v.level);editor.selected.clear()});closeModal(false);fitEditor();updateEditor();toast('Loaded “'+name+'”.')};grid.append(b)}if(!grid.children.length)p.textContent='No saved rooms yet. Save a named slot in the workshop first.';frag.append(grid);showModal('Your local chambers.',frag)};
$('modalBackdrop').addEventListener('pointerdown',e=>{if(e.target===$('modalBackdrop'))closeModal()});
function frame(time){if(!lastTime)lastTime=time;const delta=Math.min(.1,(time-lastTime)/1000);lastTime=time;frameMs=delta*1000;fps=fps*.93+(delta?1/delta:60)*.07;pollPad();if(mode==='play'&&!paused&&!world.won&&!$('modalBackdrop').classList.contains('open')){const mask=inputMask();if(mask)started=true;if(started){acc+=delta*(slow?.25:1);let n=0;while(acc>=E.DT&&n<8){simulationStep(mask);acc-=E.DT;n++;if(paused||world.won||!started)break}}}else acc=0;if(!settings.motion){for(const p of particles){p.x+=p.vx*delta;p.y+=p.vy*delta;p.vy+=80*delta;p.life-=delta*1.7}particles=particles.filter(p=>p.life>0)}if(time-uiTimer>100){updateUI();uiTimer=time}drawWorld();drawTimeline();music();requestAnimationFrame(frame)}
