window.echoLab={get state(){const w=inspection||world;return{mode,playTesting,paused,started,level:level.name,levelIndex,frame:w.frame,liveFrame:world.frame,duration:level.duration,loop:loopAttempts,echoes:recordings.length,player:E.clone({...w.player,rec:null}),actors:w.actors.map(a=>({id:a.id,x:a.x,y:a.y,carry:a.carry,grounded:a.grounded,dead:a.dead,drift:a.maxDrift,warning:a.warning})),channels:E.clone(w.channels),objects:w.objects.map(o=>({id:o.id,type:o.type,x:o.x,y:o.y,w:o.w,h:o.h,active:o.active,open:o.open,heldBy:o.heldBy,timer:o.timer})),recordedFrames:world.inputs.length,events:E.clone(world.events),divergence:E.clone(w.divergence),won:w.won,input:inputMask(),inspection:!!inspection,editor:mode==='editor'?{tool:editor.tool,selected:[...editor.selected],objectCount:editor.level.objects.length,undo:editor.undo.length,redo:editor.redo.length,zoom:editor.zoom,panX:editor.panX,panY:editor.panY,level:E.clone(editor.level),errors:E.validate(editor.level).errors}:null,audio:{enabled:audio.enabled,state:audio.ac?.state||'uninitialized',sampleRate:audio.ac?.sampleRate||null},fps}},get recordings(){return E.clone(recordings)}};
